import { elements, molecules, molecularMass, parseFormula, format, formulaHTML, reactions, atomLedger, equationHTML, convert, react, finite } from './core.js';
import { molecularSVG, particleGroup, stoichiometryArt, alchemySeal } from './art.js';
import { ExplorationWorkbench, numberField, bindNumber, metric, makeDraggable, notice, guideStep } from './components.js';
export function mountMolecule(root,ctx){
let selected='H2O',counts={},angle=0,tilt=.3,zoom=1,compare='CO2';
root.innerHTML=ExplorationWorkbench('<div class="molecule-art" tabindex="0" role="group" aria-label="分子旋轉區，拖曳或方向鍵旋轉"></div><p class="molecule-instruction">拿取原子放進陣中；外環顯示配方完成度。拖曳模型可旋轉。</p><div class="element-rack"></div>','<h3>照化學式組模型</h3><label class="select-label">要組哪種物質？<select class="molecule-select">'+Object.entries(molecules).map(([f,m])=>'<option value="'+f+'">'+f+' · '+m.name+'</option>').join('')+'</select></label><div class="atom-counts"></div><div class="button-row"><button class="secondary complete">按配方補齊</button><button class="secondary clear">清空模型</button></div>'+numberField('molecule-zoom','模型縮放',1,.65,1.35,.05,'倍')+'<div class="button-row"><button class="secondary rotate-left" aria-label="模型向左旋轉">↶ 向左</button><button class="secondary rotate-right" aria-label="模型向右旋轉">向右 ↷</button></div><button class="text-button reset-view">還原視角</button><div class="activity-status" role="status"></div><div class="molecule-readout"></div>','請照選好的化學式組裝；還沒組完時，不代表已經做出這種物質。拖曳旋轉、滾輪縮放；Tab 聚焦後也可用方向鍵。');
root.insertAdjacentHTML('beforeend','<div class="observation-panel"><h3>比較兩種物質的相對質量</h3><label>比較對象 <select class="molecule-compare">'+Object.entries(molecules).map(([f,m])=>'<option value="'+f+'" '+(f===compare?'selected':'')+'>'+f+' · '+m.name+'</option>').join('')+'</select></label><div class="molecule-comparison"></div><div class="comparison-definition"><b>怎麼從質量比找原子量？</b><br>待測原子的平均質量 ÷ 碳-12 原子質量＝待測元素原子量 ÷ 12。<br>例如氧：碳-12 的質量比約 4：3，氧原子量約為 12×4÷3＝16。使用同一標準時，兩元素的原子量比就是平均原子質量比。</div><details><summary>如果把比較標準加倍，原子真的變輕了嗎？</summary><div class="standard-demo"><p>原子本身沒有變重或變輕。下面只是試著換一把比較用的尺，不改課本採用的數值。</p><button class="secondary reference-toggle">把假想質量標準加倍</button><p class="reference-result">正式標準：碳-12 的相對質量是 12。</p><p>講義的另一種問法是「把碳-12 的相對數值改訂成 24」。那相當於把比較單位縮小一半，所有相對數值加倍；原子本身仍沒有變重，現行 1 mol 的粒子數也不變。</p></div></details></div>');
function done(){const wanted=parseFormula(selected);return Object.entries(wanted).every(([e,n])=>counts[e]===n);}
function draw(){const m=molecules[selected],wanted=parseFormula(selected),missing=Object.entries(wanted).filter(([e,n])=>(counts[e]||0)<n);root.querySelectorAll('[data-element]').forEach(b=>{const e=b.dataset.element,remaining=Math.max(0,(wanted[e]||0)-(counts[e]||0));b.disabled=!remaining;b.setAttribute('aria-label',elements[e].name+'：'+(!wanted[e]?'這個配方用不到':remaining?'還要 '+remaining+' 個':'已放足'));b.dataset.needed=remaining?String(remaining):'';});guideStep(root,missing.length?'還需要：'+missing.map(([e,n])=>(n-(counts[e]||0))+' 個'+elements[e].name+'原子').join('、'):'模型組好了！看看 1 mol 有幾克',missing.length?'拖原子進入圓陣，或點原子按鈕。灰色的原子這次不用再放。':'拖曳模型可以旋轉；下方可比較其他物質，右側可換配方。',missing.length?'[data-element="'+missing[0][0]+'"]':'.molecule-select');root.querySelector('.molecule-art').innerHTML=molecularSVG(m,{angle,tilt,zoom,counts});const expected=parseFormula(selected);root.querySelector('.atom-counts').innerHTML=Object.entries(expected).map(([e,n])=>'<div class="atom-line"><b style="--atom:'+elements[e].color+'">'+e+'</b><span>'+elements[e].name+' · Aᵣ='+elements[e].ar+'</span><strong>'+(counts[e]||0)+' / '+n+'</strong><button class="remove-atom" data-remove="'+e+'" aria-label="移除一個'+elements[e].name+'原子" '+(!(counts[e]>0)?'disabled':'')+'>−</button></div>').join('');root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const el=b.dataset.remove;counts[el]=Math.max(0,(counts[el]||0)-1);draw();root.querySelector((counts[el]>0?'[data-remove="':'[data-element="')+el+'"]').focus();});const sum=Object.entries(counts).reduce((s,[e,n])=>s+n*elements[e].ar,0);root.querySelector('.molecule-readout').innerHTML=metric(done()?(m.kind==='式單位'?'相對式量':'相對分子量'):'目前加入的相對質量總和',format(sum))+'<p class="small">'+(done()?Object.entries(expected).map(([e,n])=>n+' × '+elements[e].ar).join(' ＋ ')+' ＝ '+format(sum)+'（無單位）':'配方尚未完成，不能把這組原子當成 '+selected+'。')+'</p>';root.querySelector('.molecule-readout').insertAdjacentHTML('beforeend','<div class="mass-contribution" aria-label="各元素的相對質量貢獻">'+Object.entries(counts).filter(([,n])=>n>0).map(([e,n])=>'<span title="'+e+'：'+n*elements[e].ar+'" style="width:'+(n*elements[e].ar/sum*100)+'%;background:'+elements[e].color+'"></span>').join('')+'</div><div class="mass-contribution-key">'+Object.entries(counts).filter(([,n])=>n>0).map(([e,n])=>'<span>'+e+'：'+n*elements[e].ar+'</span>').join('')+'</div>');root.querySelector('.molecule-comparison').innerHTML='<div class="metrics">'+metric(formulaHTML(selected),format(molecularMass(selected)))+metric(formulaHTML(compare),format(molecularMass(compare)))+metric('前者 ÷ 後者',format(molecularMass(selected)/molecularMass(compare)),'倍')+'</div><p class="small">比較一個分子／式單位的相對質量；離子晶體以式單位比較。</p>';if(!done())notice(root,'還沒組好：'+missing.map(([e,n])=>'還要 '+(n-(counts[e]||0))+' 個'+elements[e].name+'原子').join('、')+'。');if(done()){root.querySelector('.molecule-readout').insertAdjacentHTML('beforeend','<div class="molar-handoff"><span>下一步：走向化學計量</span><b>1 mol '+formulaHTML(selected)+' → '+format(sum)+' g</b><p>相對質量沒有單位；莫耳質量是 '+format(sum)+' g/mol。數值相同，意義不同。</p></div>');notice(root,'配方完成。現在可旋轉模型，並比較兩種物質的相對質量。');ctx.mark('assembled');}}
function add(e){if(!ctx.predict())return;const wanted=parseFormula(selected);if(!wanted[e]){notice(root,'這個化學式沒有 '+e+'，不能把它加入配方。');return;}if((counts[e]||0)>=wanted[e]){notice(root,e+' 已達配方數量；多加會改變化學式。');return;}counts[e]=(counts[e]||0)+1;draw();}
function rack(){root.querySelector('.element-rack').innerHTML=['H','C','O','S','Na','Cl','Al'].map(e=>'<button class="element-token" data-element="'+e+'" style="--atom:'+elements[e].color+'" aria-label="加入'+elements[e].name+'原子"><b>'+e+'</b><small>'+elements[e].ar+'</small></button>').join('');root.querySelectorAll('[data-element]').forEach(b=>makeDraggable(b,root.querySelector('.molecule-art'),()=>add(b.dataset.element),root.querySelector('.activity-status')));}
root.querySelector('.molecule-select').onchange=e=>{selected=e.target.value;counts={};notice(root,'依化學式加入正確數量的原子。');draw();};
root.querySelector('.molecule-compare').onchange=e=>{compare=e.target.value;draw();};
root.querySelector('.complete').onclick=()=>{if(!ctx.predict())return;counts=parseFormula(selected);draw();};
root.querySelector('.clear').onclick=()=>{counts={};draw();notice(root,'模型已清空，可以重新組裝。');};
const setZoom=bindNumber(root,'molecule-zoom',v=>{zoom=v;draw();});
root.querySelector('.rotate-left').onclick=()=>{angle-=.25;draw();};root.querySelector('.rotate-right').onclick=()=>{angle+=.25;draw();};root.querySelector('.reset-view').onclick=()=>{angle=0;tilt=.3;zoom=1;setZoom(1);draw();};
const area=root.querySelector('.molecule-art');area.onselectstart=area.ondragstart=e=>e.preventDefault();let drag=null;area.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();area.focus({preventScroll:true});area.classList.add('is-rotating');drag={x:e.clientX,y:e.clientY};area.setPointerCapture(e.pointerId);};area.onpointermove=e=>{if(!drag)return;e.preventDefault();angle+=(e.clientX-drag.x)*.012;tilt+=(e.clientY-drag.y)*.01;drag={x:e.clientX,y:e.clientY};draw();};area.onpointerup=area.onpointercancel=()=>{drag=null;area.classList.remove('is-rotating');};area.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')angle-=.2;if(e.key==='ArrowRight')angle+=.2;if(e.key==='ArrowUp')tilt-=.2;if(e.key==='ArrowDown')tilt+=.2;draw();}};area.addEventListener('wheel',e=>{if(document.activeElement!==area)return;e.preventDefault();zoom=Math.max(.65,Math.min(1.35,Math.round((zoom-e.deltaY*.001)*20)/20));setZoom(zoom);draw();},{passive:false});
let doubled=false;root.querySelector('.reference-toggle').onclick=e=>{doubled=!doubled;e.target.textContent=doubled?'恢復正式標準：碳-12':'把假想質量標準加倍';root.querySelector('.reference-result').textContent=doubled?'假想比較尺變成 2 倍，碳-12 的比值會成為 6；但同一顆碳原子的真實質量完全沒變。正式相對原子質量定義仍用 1/12 碳-12。':'正式標準：碳-12 的相對質量是 12。';};
rack();draw();return{reset(){counts={};angle=0;tilt=.3;zoom=1;setZoom(1);draw();}};
}
export function mountBalancer(root,ctx){
let id='water',coeff=[1,1,1],solved=new Set(ctx.data.balanced||[]);
root.innerHTML='<div class="equation-workbench"><div class="balance-top"><label>反應題目 <select class="balance-select">'+['water','magnesium','iron','peroxide'].map(id=>'<option value="'+id+'">'+reactions[id].name+'</option>').join('')+'</select></label><span class="balance-done"></span></div><div class="balance-alchemy"></div><div class="equation-controls" aria-label="只可修改係數"></div><div class="balance-models"></div><div class="balance-ledger"></div><div class="button-row"><button class="secondary balance-hint">給我一個提示</button><button class="text-button balance-reset">係數全部回到 1</button></div><div class="activity-status" role="status"></div><p class="model-note">每一框表示一個分子，或一份化學式的組成。MgO、Fe₂O₃ 的框只表示比例，不是獨立分子。右下角的小數字不能改。</p></div>';
root.insertAdjacentHTML('beforeend','<details class="balance-method"><summary>不知道從哪裡開始？看配平的三步方法</summary><p>先根據實驗確認反應物和生成物的化學式，再調整係數。配平不能證明任意想像的反應一定會發生。</p><ol><li>先選一種物質，暫定它的係數為 1。常從組成較複雜的物質開始。</li><li>以水為例：先設 H₂O 為 1，配氫得到 H₂ 為 1，再配氧得到 O₂ 為 1/2。</li><li>整式乘 2：2H₂＋O₂→2H₂O；最後檢查每種原子數，再約成最簡整數比。</li></ol><p><b>反應前後總共有幾個分子，不一定相同。</b>水的例子是 3 個反應物分子形成 2 個水分子，但 H 仍為 4 個、O 仍為 2 個。</p><p>操作器最後只填正整數係數；不能改動下標。</p></details>');
function draw(){const r=reactions[id],ledger=atomLedger(r,coeff),all=[...r.left,...r.right];const matched=ledger.rows.filter(x=>x.left===x.right).length;root.querySelector('.balance-alchemy').innerHTML='<div class="balance-emblem">'+alchemySeal(matched+' / '+ledger.rows.length,'種元素數量相同',matched/ledger.rows.length)+'</div><div><span class="eyebrow">守恆煉成陣 · 左右原子一樣多，才能算產量</span><h3>'+(ledger.balanced?'左右原子一樣多了！來看莫耳數的比例':'調整係數，讓每種原子都對上')+'</h3><p>'+(ledger.balanced?all.map((f,i)=>coeff[i]+' mol '+formulaHTML(f)).join(' ： '):'每對上一種原子，圓環就多亮一段。全部對上後，才能用係數算產量。')+'</p><small>'+(ledger.balanced?'係數比＝莫耳數比；質量比還要各自乘上莫耳質量。':'只改係數；化學式的下標保持不變。')+'</small></div>';root.querySelector('.equation-controls').innerHTML=all.map((f,i)=>(i===r.left.length?'<strong class="equation-arrow">→</strong>':i?'<span>＋</span>':'')+'<div class="coefficient"><div><button data-adjust="'+i+'" data-delta="-1" aria-label="減少 '+f+' 係數" '+(coeff[i]<=1?'disabled':'')+'>−</button><output aria-label="'+f+' 係數">'+coeff[i]+'</output><button data-adjust="'+i+'" data-delta="1" aria-label="增加 '+f+' 係數" '+(coeff[i]>=12?'disabled':'')+'>＋</button></div><b>'+formulaHTML(f)+'</b></div>').join('');root.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{if(!ctx.predict())return;const focusLabel=b.getAttribute('aria-label');coeff[Number(b.dataset.adjust)]+=Number(b.dataset.delta);draw();[...root.querySelectorAll('[data-adjust]')].find(x=>x.getAttribute('aria-label')===focusLabel)?.focus();});root.querySelector('.balance-models').innerHTML=all.map((f,i)=>'<div class="particle-species"><small class="species-side">'+(i<r.left.length?'反應物':'生成物')+'</small><strong>'+coeff[i]+formulaHTML(f)+'</strong>'+particleGroup(f,coeff[i])+'</div>').join('');root.querySelector('.balance-ledger').innerHTML='<table><thead><tr><th>元素</th><th>反應物原子數</th><th>生成物原子數</th><th>對照</th></tr></thead><tbody>'+ledger.rows.map(x=>'<tr><th>'+x.e+'</th><td><div class="atom-bar" style="width:'+Math.max(2,x.left*6)+'px"></div>'+x.left+'</td><td><div class="atom-bar right" style="width:'+Math.max(2,x.right*6)+'px"></div>'+x.right+'</td><td>'+(x.left===x.right?'✓ 相等':(x.left>x.right?'右邊少 ':'左邊少 ')+Math.abs(x.left-x.right))+'</td></tr>').join('')+'</tbody></table>';
if(ledger.balanced&&ledger.minimal){solved.add(id);ctx.data.balanced=[...solved];ctx.save();notice(root,'平衡成功！每種元素的原子數相同，而且是最簡整數比。');if(solved.size===4)ctx.mark('four-balanced');}
else if(ledger.balanced)notice(root,'原子數對上了！再把係數一起除以相同的數，約成最簡整數比。');
else notice(root,ledger.rows.filter(x=>x.left!==x.right).map(x=>x.e+'：左 '+x.left+'、右 '+x.right).join('；')+'。調整整組物質的係數。');
guideStep(root,ledger.balanced?(ledger.minimal?'配平成功！下一步看莫耳數比':'原子數對上了，再把係數約小'):'先找左右數量不同的原子',ledger.balanced?'係數代表莫耳數的比例。換另一題再練習，不能把下標改掉。':'看下方表格的差幾個，再用化學式上方的＋／−改份數。',ledger.balanced?'.balance-select':'.equation-controls');root.querySelector('.balance-done').textContent='已完成 '+solved.size+' / 4 題';root.querySelector('.equation-workbench').classList.toggle('balanced',ledger.balanced&&ledger.minimal);}
root.querySelector('.balance-select').onchange=e=>{id=e.target.value;coeff=reactions[id].coeff.map(()=>1);draw();};root.querySelector('.balance-reset').onclick=()=>{coeff=coeff.map(()=>1);draw();};root.querySelector('.balance-hint').onclick=()=>{notice(root,{water:'右邊先放 2 份 H₂O，氧就和 1 份 O₂ 相等，再調整 H₂。',magnesium:'O₂ 有 2 個氧，先讓右側出現 2 份 MgO。',iron:'氧的最小公倍數是 6：試試 3O₂ 和 2Fe₂O₃，再配鐵。',peroxide:'先讓 H₂O₂ 與 H₂O 係數同為 2，剩下的氧組成 O₂。'}[id]);};
draw();return{reset(){solved.clear();ctx.data.balanced=[];coeff=coeff.map(()=>1);draw();}};
}
export function mountStoich(root,ctx){
 let id='peroxide',unit='g',value=34,productIndex=1,phase=0,calcStep=0,unlocked=0,current=null;
 let level=1,levels=new Set(ctx.data.stoichLevels||[]);
 const units={g:'公克 g',mg:'毫克 mg',kg:'公斤 kg',mol:'莫耳 mol',particles:'粒子個數'};
 const names={H2O2:'過氧化氫',H2O:'水',O2:'氧氣',Mg:'鎂',MgO:'氧化鎂',CaCO3:'碳酸鈣',CaCl2:'氯化鈣',CO2:'二氧化碳'};
 root.innerHTML='<div class="stoich-stage-nav" role="group" aria-label="計量操作三階段">'+['選材料用量','一起算產量','看結果'].map((s,i)=>'<button data-stage="'+i+'"><span>'+(i+1)+'</span>'+s+'</button>').join('')+'</div>'+ExplorationWorkbench('<div class="stoich-visual"></div>','<div class="stoich-stage-controls"></div>','教學模型：假設反應順利完成，材料沒有損失。若有另一種反應物，會給得夠多，不會先用完。')+'<details class="workshop-challenges"><summary>自己算一次：三個小關卡</summary><div class="challenge-inner"><div class="level-tabs" role="group" aria-label="工坊三關">'+[1,2,3].map(n=>'<button data-level="'+n+'"></button>').join('')+'</div><div class="level-question"></div><div class="answer-row"><label>我的答案<input class="level-answer" type="number" step="any" min="0"></label><span class="level-unit"></span><button class="primary level-check">檢查本關</button></div><p class="level-feedback" role="status"></p><details class="final-challenge"><summary>挑戰：里昂需要 8 g 氧氣</summary><p>有 40 g 過氧化氫水溶液，其中一半質量是 H₂O₂，另一半是水。完全分解後，能收集到 8 g 氧氣嗎？先算裡面有幾克 H₂O₂。</p><div class="answer-row"><label>算出的氧氣質量<input class="challenge-answer" type="number" step="any" min="0"></label><span>g</span><button class="secondary challenge-check">檢查挑戰</button></div><p class="challenge-feedback" role="status"></p></details></div></details>';
 const control=root.querySelector('.stoich-stage-controls');
 function inUnit(grams){const c=convert(grams,'g',reactions[id].left[0]);return unit==='mol'?c.mol:unit==='particles'?Math.round(c.particles):c.mass/{g:1,mg:.001,kg:1000}[unit];}
 function compute(raw){try{if(raw===''||!Number.isFinite(Number(raw))||Number(raw)<0)throw new Error('請填入 0 或大於 0 的數字。');if(Number(raw)>1e30)throw new Error('數字太大了，請把材料用量調小。');finite(raw,0,1e30);if(unit==='particles'&&!Number.isInteger(Number(raw)))throw new Error('粒子要一個一個數，請輸入整數。');const r=reactions[id],f=r.left[0],c=convert(Number(raw),unit,f);if(c.mass>1e6)throw new Error('材料最多可輸入 1,000,000 g，請把數字調小。');const masses=r.left.map((formula,i)=>i===0?c.mass:c.mol/r.coeff[0]*r.coeff[i]*molecularMass(formula)*2+1),out=react(id,masses);value=Number(raw);current={r,f,c,out,product:out.products[productIndex]};return '';}catch(e){current=null;return e.message;}}
 function steps(){const {r,c,product}=current,a=r.coeff[0],b=r.coeff[r.left.length+productIndex],M=molecularMass(product.formula);return[
  {title:'材料有幾莫耳？',why:'每 '+c.M+' g 是 1 mol，所以用克數除以 '+c.M+'。',formula:format(c.mass)+' g ÷ '+c.M+' g/mol',answer:c.mol,unit:'mol',hint:'算 '+format(c.mass)+' ÷ '+c.M+'，就知道材料有幾莫耳。'},
  {title:'會有幾莫耳產物？',why:'配方是 '+a+' mol '+names[current.f]+' → '+b+' mol '+names[product.formula]+'，所以乘 '+b+'/'+a+'。',formula:format(c.mol)+' mol × '+b+'/'+a,answer:product.mol,unit:'mol',hint:'用剛才的 '+format(c.mol)+' mol，乘上「產物係數 '+b+' ÷ 反應物係數 '+a+'」。'},
  {title:'產物有幾克？',why:'1 mol '+names[product.formula]+' 是 '+M+' g，所以再乘 '+M+'。',formula:format(product.mol)+' mol × '+M+' g/mol',answer:product.mass,unit:'g',hint:'用 '+format(product.mol)+' × '+M+'，把產物的莫耳數換回克數。'}
 ];}
 function nav(){root.querySelectorAll('[data-stage]').forEach(b=>{const n=Number(b.dataset.stage);b.disabled=n>unlocked;b.setAttribute('aria-current',n===phase?'step':'false');});}
 function drawVisual(){nav();const area=root.querySelector('.stoich-visual');area.dataset.phase=String(phase);if(!current){area.innerHTML='<div class="invalid-state"><h3>先把用量改好</h3><p>右邊會告訴你要改哪個數字。</p></div>';return;}const {f,c,r,out,product}=current;
 const caption=phase===0?'選好材料用量，再來算產物。':phase===1?'先算算看，最後再顯示產物的量。':'這是計算得到的理論結果。';
 area.innerHTML='<div class="stoich-board-caption"><span class="eyebrow">精準煉成工作台</span><b>'+caption+'</b></div><div class="stoich-apparatus">'+stoichiometryArt(f,c.mass,out.products,{revealed:phase===2})+'</div>';
 if(phase===0)area.insertAdjacentHTML('beforeend','<div class="stoich-start-note"><b>你放入 '+format(c.mass)+' g '+names[f]+'</b><p>想知道能得到多少'+names[product.formula]+'？選好用量後，按右邊「開始計算」。</p></div>');
 if(phase===1){const s=steps()[calcStep];area.insertAdjacentHTML('beforeend','<section class="calc-focus"><div class="calc-track">'+['克換莫耳','照比例算','換回克數'].map((x,i)=>'<span class="'+(i===calcStep?'active':i<calcStep?'done':'')+'">'+(i<calcStep?'✓':i+1)+' '+x+'</span>').join('')+'</div><div class="calc-focus-heading"><div class="calc-mini-seal">'+alchemySeal(String(calcStep+1),'計算步驟',(calcStep+1)/3)+'</div><div><h3>'+s.title+'</h3><p>'+s.why+'</p></div></div><div class="calc-formula">'+s.formula+' <span>＝ ? '+s.unit+'</span></div><details class="calc-equation"><summary>看看這個反應的配方</summary><div class="equation">'+equationHTML(id)+'</div><p>前面的係數是莫耳數比，不能直接當成克數比。</p></details></section>');}
 if(phase===2)area.insertAdjacentHTML('beforeend','<section class="stoich-result-card"><span class="eyebrow">算出來了！</span><h3>'+format(c.mass)+' g '+formulaHTML(f)+' 可以生成</h3><div class="stoich-result-number" data-result="product-mass">'+format(product.mass)+' <small>g '+formulaHTML(product.formula)+'</small></div><p>改變材料用量，產量也會跟著改變。</p><details class="result-recap"><summary>回看剛剛的三步計算</summary><ol>'+steps().map(s=>'<li><b>'+s.title+'</b><p>'+s.formula+'＝'+format(s.answer)+' '+s.unit+'</p></li>').join('')+'</ol></details><details class="result-particles"><summary>這份材料有多少個粒子？</summary><p>'+format(c.mass)+' g '+formulaHTML(f)+'＝'+format(c.mol)+' mol，約有 '+format(c.particles)+' 個'+(f==='Mg'?'鎂原子':f==='CaCO3'?'碳酸鈣式單位':'過氧化氫分子')+'。</p><p>粒子數＝莫耳數×6.02×10²³。</p></details></section>');
 }
 function resetCalculation(){unlocked=0;calcStep=0;}
 function syncDose(raw){resetCalculation();const error=compute(raw),input=control.querySelector('.stoich-value'),range=control.querySelector('.stoich-dose-slider');input.setCustomValidity(error);control.querySelector('.stoich-error').textContent=error;control.querySelector('.stoich-start').disabled=!!error;if(current){input.value=String(value);range.max=String(inUnit(Math.max(100,current.c.mass)));range.value=String(value);guideStep(root,'先選材料用量，再按「開始計算」','可以拖滑桿、直接輸入數字，或點常用用量。','.stoich-start');}else guideStep(root,'這個用量需要調整',error,'.stoich-value');drawVisual();}
 function show(){nav();drawVisual();if(phase===0){const r=reactions[id];control.innerHTML='<span class="panel-eyebrow">第 1 階段</span><h3>先選材料用量</h3><label class="select-label">做哪個反應？<select class="stoich-reaction">'+['peroxide','magnesium','limestone'].map(x=>'<option value="'+x+'" '+(x===id?'selected':'')+'>'+reactions[x].name+'</option>').join('')+'</select></label><label class="select-label">想算哪個產物？<select class="stoich-product">'+r.right.map((f,i)=>'<option value="'+i+'" '+(i===productIndex?'selected':'')+'>'+names[f]+'（'+f+'）</option>').join('')+'</select></label><label class="select-label dose-label">'+names[r.left[0]]+'的用量（'+units[unit]+'）<input class="stoich-value" type="number" min="0" max="1e30" step="any" value="'+value+'"></label><input class="stoich-dose-slider" aria-label="材料用量滑桿" type="range" min="0" max="'+inUnit(Math.max(100,current?.c.mass||0))+'" step="any" value="'+value+'"><div class="dose-presets">'+({peroxide:[17,34,68],magnesium:[6,12,24],limestone:[5,10,20]}[id]).map(v=>'<button data-dose="'+v+'">'+v+' g</button>').join('')+'</div><p class="stoich-error field-error" role="status"></p><p class="excess-note">'+(r.left.length>1?'另一種材料給得夠多，不會先用完（足量）。':'這裡只算 H₂O₂ 的量，不包含溶液裡的水。')+'</p><button class="primary stoich-start">開始計算 →</button><details class="input-unit-options"><summary>想換別的單位輸入？</summary><label class="select-label">單位<select class="stoich-unit">'+Object.entries(units).map(([u,t])=>'<option value="'+u+'" '+(u===unit?'selected':'')+'>'+t+'</option>').join('')+'</select></label><p>換單位不會改變材料多少。例如 1 g＝1,000 mg。</p></details><button class="text-button stoich-reset">恢復 34 g 過氧化氫</button>';
 control.querySelector('.stoich-value').oninput=e=>syncDose(e.target.value);
 control.querySelector('.stoich-dose-slider').oninput=e=>syncDose(unit==='particles'?Math.round(Number(e.target.value)):Number(Number(e.target.value).toPrecision(4)));
 control.querySelectorAll('[data-dose]').forEach(b=>b.onclick=()=>syncDose(inUnit(Number(b.dataset.dose))));
 control.querySelector('.stoich-reaction').onchange=e=>{id=e.target.value;productIndex=reactions[id].right.length-1;resetCalculation();compute(value);show();};
 control.querySelector('.stoich-product').onchange=e=>{productIndex=Number(e.target.value);resetCalculation();compute(value);show();};
 control.querySelector('.stoich-unit').onchange=e=>{const grams=current?.c.mass??34;unit=e.target.value;value=inUnit(grams);resetCalculation();compute(value);show();control.querySelector('.input-unit-options').open=true;};
 control.querySelector('.stoich-reset').onclick=()=>reset();
 control.querySelector('.stoich-start').onclick=()=>{if(!current||!ctx.predict())return;phase=1;unlocked=Math.max(unlocked,1);present();};
 if(!current)syncDose(control.querySelector('.stoich-value').value);else guideStep(root,'先選材料用量，再按「開始計算」','一次做一件事：這一步只要決定放多少材料。','.stoich-start');
 }else if(phase===1){const s=steps()[calcStep];control.innerHTML='<span class="panel-eyebrow">第 2 階段 · 計算 '+(calcStep+1)+' / 3</span><h3>'+s.title+'</h3><p class="calc-instruction">跟著左邊的算式，填入你的答案。</p><label class="calc-answer-label">我的答案<div class="calc-answer-row"><input class="calc-answer" type="number" min="0" step="any" inputmode="decimal"><span>'+s.unit+'</span></div></label><button class="primary calc-check">檢查答案</button><button class="text-button calc-hint">給我一個提示</button><p class="calc-feedback" role="status"></p><button class="primary calc-next" hidden>'+(calcStep<2?'下一步 →':'看模型結果 →')+'</button><button class="text-button calc-back">'+(calcStep===0?'← 回去改用量':'← 回看上一步')+'</button>';
 const answer=control.querySelector('.calc-answer'),feedback=control.querySelector('.calc-feedback');
 control.querySelector('.calc-check').onclick=()=>{const raw=answer.value,n=Number(raw);if(raw===''||!Number.isFinite(n)||n<0){feedback.className='calc-feedback incorrect';feedback.textContent='先填一個 0 或大於 0 的數字。';return;}const ok=s.answer===0?n===0:Math.abs(n-s.answer)<=Math.abs(s.answer)*.005;feedback.className='calc-feedback '+(ok?'correct':'incorrect');feedback.textContent=(ok?'✓ 算對了！':'再看一次：')+s.formula+'＝'+format(s.answer)+' '+s.unit+'。'+(ok?'':s.why);control.querySelector('.calc-next').hidden=false;control.querySelector('.calc-next').textContent=ok?(calcStep<2?'下一步 →':'看模型結果 →'):(calcStep<2?'看懂了，用這個結果繼續 →':'看懂了，看模型結果 →');};
 answer.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();control.querySelector('.calc-check').click();}};answer.oninput=()=>{control.querySelector('.calc-next').hidden=true;feedback.textContent='';};
 control.querySelector('.calc-hint').onclick=()=>{feedback.className='calc-feedback hint';feedback.textContent=s.hint;};
 control.querySelector('.calc-next').onclick=()=>{if(calcStep<2)calcStep++;else{phase=2;unlocked=2;ctx.mark('guided-stoichiometry');}present();};
 control.querySelector('.calc-back').onclick=()=>{if(calcStep>0)calcStep--;else phase=0;present();};
 guideStep(root,s.title,'這次只算這一步。填入答案後按 Enter，也可以按「檢查答案」。','.calc-answer');answer.focus({preventScroll:true});
 }else{control.innerHTML='<span class="panel-eyebrow">第 3 階段</span><h3>換個用量，試試看</h3><p class="result-prompt">如果材料變成兩倍，產物也會變成兩倍嗎？</p><button class="primary stoich-again">改用量，再算一次</button><button class="secondary stoich-practice">換我自己算題目</button><button class="text-button stoich-review">回看三步計算</button>';
 control.querySelector('.stoich-again').onclick=()=>{phase=0;present();};control.querySelector('.stoich-practice').onclick=()=>{const p=root.querySelector('.workshop-challenges');p.open=true;p.scrollIntoView({behavior:'auto',block:'start'});p.querySelector('.level-answer').focus({preventScroll:true});};control.querySelector('.stoich-review').onclick=()=>{phase=1;calcStep=0;present();};guideStep(root,'你已用三步算出產量','換一個用量比較，或到小關卡自己算一次。','.stoich-again');}}
 function present(){show();root.querySelector('.stoich-stage-nav').scrollIntoView({behavior:'instant',block:'start'});}
 root.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.stage);if(n<=unlocked){phase=n;present();}});
 const tasks={1:{q:'18 g 水，每 1 mol 是 18 g。這些水有幾 mol？',unit:'mol',a:1,reason:'18÷18＝1 mol。'},2:{q:'0.5 mol 水約有幾個水分子？很大的數可寫成 3.01e23。',unit:'個分子',a:3.01e23,reason:'0.5×6.02×10²³＝3.01×10²³ 個水分子。'},3:{q:'8.4 g 小蘇打和夠多的醋酸反應，產生幾克 CO₂？1 mol 小蘇打是 84 g，可生成 1 mol、44 g 的 CO₂。',unit:'g',a:4.4,reason:'8.4÷84＝0.1 mol；0.1×1×44＝4.4 g CO₂。'}};
 function showLevel(){const t=tasks[level];root.querySelector('.level-question').innerHTML='<h3>第 '+level+' 關</h3><p>'+t.q+'</p>';root.querySelector('.level-unit').textContent=t.unit;root.querySelector('.level-answer').value='';root.querySelector('.level-feedback').textContent='';root.querySelectorAll('[data-level]').forEach(b=>{const n=Number(b.dataset.level);b.setAttribute('aria-pressed',String(n===level));b.textContent=['1 · 克與莫耳','2 · 莫耳與粒子','3 · 算產物'][n-1]+(levels.has(n)?' ✓':'');});}
 root.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=Number(b.dataset.level);showLevel();});
 root.querySelector('.level-check').onclick=()=>{if(!ctx.predict())return;const raw=root.querySelector('.level-answer').value,n=Number(raw),t=tasks[level];if(raw===''||!Number.isFinite(n)||n<0){root.querySelector('.level-feedback').textContent='請輸入 0 或大於 0 的數字。';return;}const ok=Math.abs(n-t.a)<=Math.max(t.a*.005,1e-8);if(ok){levels.add(level);ctx.data.stoichLevels=[...levels];ctx.save();root.querySelector('[data-level="'+level+'"]').textContent=['1 · 克與莫耳','2 · 莫耳與粒子','3 · 算產物'][level-1]+' ✓';if(levels.size===3)ctx.mark('three-workshop-levels');}root.querySelector('.level-feedback').textContent=(ok?'✓ 正確！':'正確的算法是：')+t.reason;};
 root.querySelector('.challenge-check').onclick=()=>{const raw=root.querySelector('.challenge-answer').value,answer=react('peroxide',[20]).products[1].mass,ok=raw!==''&&Number.isFinite(Number(raw))&&Math.abs(Number(raw)-answer)<.05;root.querySelector('.challenge-feedback').textContent=(ok?'✓ 正確，氧氣夠用！':'算出的氧氣約 9.41 g，所以夠用。')+'先算 H₂O₂：40×50%＝20 g。再算氧氣：20÷34×(1/2)×32≈9.41 g。原來的 20 g 水，加上新生成的約 10.59 g 水，再加氧氣，總共仍是 40 g。';};
 function reset(){id='peroxide';unit='g';value=34;productIndex=1;phase=0;resetCalculation();compute(value);show();}
 compute(value);show();showLevel();return{reset(){levels.clear();ctx.data.stoichLevels=[];level=1;reset();showLevel();root.querySelector('.workshop-challenges').open=false;root.querySelector('.challenge-answer').value='';root.querySelector('.challenge-feedback').textContent='';}};
}
